def current_dir():
    return os.getcwd()


def touch(filepath):
    open(filepath, 'a').close()


class InvalidRepo(Exception):
    pass


class ToolDownloader(object):
    PACKED_TOOL_NAME = 'gnb_logs.zip'

    def __init__(self, directory):
        self._directory = directory

    def download(self):
        if not self.already_cloned():
            self.remove_potential_leftovers_from_previous_runs()
            try:
                self.clone()
                self.checkout()
            except subprocess.CalledProcessError:
                raise InvalidRepo
            self.extract()
            self.remove_git_directory()

    def already_cloned(self):
        return os.path.exists(os.path.join(self._directory, 'gnb_logs')) and \
            os.path.exists(os.path.join(self._directory, 'gnb_logs', 'gnb_logs')) and \
            os.path.exists(os.path.join(self._directory, 'gnb_logs', 'config.ini'))

    def remove_potential_leftovers_from_previous_runs(self):
        if self._dir_is_located_in_tmp():
            logger.info('Tool not present or broken, to ensure correct clone removing: {}'.format(self._directory))
            shutil.rmtree(self._directory, ignore_errors=True)
        else:
            logger.warning('Tool download_target_directory not in "/tmp", '
                           'will not be removed, even if errors occur')

    def _dir_is_located_in_tmp(self):
        return re.match(r'/tmp/.', self._directory)

    def clone(self):
        with open(os.devnull, 'w') as devnull:
            logger.info('Cloning gnb_logs tool repository started. Directory: {}'.format(self._directory))
            subprocess.check_call(['git', 'clone', REPOSITORY, self._directory],
                                  stdout=devnull, stderr=devnull)
            logger.info('Cloning gnb_logs tool repository finished')

    def checkout(self):
        with open(os.devnull, 'w') as devnull:
            logger.info('Checking out: {}'.format(CHECKOUT_TARGET))
            with change_dir(self._directory):
                subprocess.check_call(['git', 'checkout', CHECKOUT_TARGET], stdout=devnull, stderr=devnull)
            logger.info('Checking out done')

    def extract(self):
        with zipfile.ZipFile(self.packed_tool_path(), 'r') as packed_tool:
            logger.info('Unpacking gnb_logs tool to {}'.format(self._directory))
            packed_tool.extractall(self._directory)
            logger.info('gnb_logs tool is unpacked')

    def remove_git_directory(self):
        git_directory_path = os.path.join(self._directory, '.git')
        logger.info('Removing unnecessary .git directory: {}'.format(git_directory_path))
        shutil.rmtree(git_directory_path)
        logger.info('Removing finished')

    def packed_tool_path(self):
        return os.path.join(self._directory, self.PACKED_TOOL_NAME)


class ConfigInjector(object):
    CONFIG_FILENAME = 'config.ini'

    def __init__(self, tool_directory, config):
        self._config_directory = os.path.join(tool_directory, self.CONFIG_FILENAME)
        self._config = config

    def set(self):
        with open(self._config_directory, 'w') as config:
            config.write(self._config)


class GnbLogs(object):
    EXECUTABLE_NAME = 'gnb_logs'
    READINESS_LOG_NAME = 'emil_readiness_handler.log'
    DEFAULT_FLAGS = '-E -v1'

    def __init__(self, tool_directory, flags=None):
        self._tool_directory = tool_directory
        self._collecting_process = None
        self._flags = flags if flags else self.DEFAULT_FLAGS

    def run(self):
        logger.info('Starting Emil logs capturing')
        stdout_path = self.readines_log_path()

        with open(stdout_path, 'wb+') as stdout_log, open(stdout_path, 'rb') as readiness_log, open(os.devnull, 'w'):
            os.chmod(self.tool_path(), 0o777)
            command = [self.tool_path(), '10.0.1.2', self._flags]
            logger.info('Executing command: {}'.format(' '.join(command)))
            self._collecting_process = subprocess.Popen(command, stdout=stdout_log, stderr=stdout_log)

            logger.info('Waiting for Emil logs capturing to start')
            timeout_event = Event()
            with TimerGuard(timeout_handler=timeout_event.set, seconds=CAPTURE_READINESS_TIMEOUT):
                while not (timeout_event.is_set() or self._is_capturing_ready(readiness_log)):
                    readiness_log.seek(readiness_log.tell())
                    time.sleep(0.1)

            if timeout_event.is_set():
                self._collecting_process.kill()
                self._collecting_process.wait()
                self._collecting_process = None
                logger.warn('Capturing Emil logs did not started in given time')
                return

        logger.info('Capturing Emil logs started')

    def stop(self):
        if dryrun_is_set():
            return

        if self._collecting_process is not None:
            logger.info('Finishing Emil logs capturer')
            self._stop_tool()

            timeout_event = Event()
            with TimerGuard(timeout_handler=timeout_event.set, seconds=CAPTURE_STOP_TIMEOUT), open(self.readines_log_path(), 'rb') as readiness_log:
                while not (timeout_event.is_set() or self._collecting_ended(readiness_log)):
                    time.sleep(0.1)

            if timeout_event.is_set():
                logger.warn('Capturing Emil logs did not stop in given time')
                self._collecting_process.kill()

            self._collecting_process.wait()
            logger.info('Capturing Emil logs finished')

    def tool_path(self):
        return os.path.join(self._tool_directory, self.EXECUTABLE_NAME)

    def readines_log_path(self):
        return os.path.join(self._tool_directory, self.READINESS_LOG_NAME)

    def _is_capturing_ready(self, logfile):
        lines = logfile.readlines()
        stop_condition = \
            any('stop_mon.log' in line.decode('utf-8').strip() for line in lines) or \
            any('to stop trace' in line.decode('utf-8').strip() for line in lines)
        return stop_condition

    def _collecting_ended(self, logfile):
        lines = logfile.readlines()
        stop_condition = \
            any('Done' in line.decode('utf-8').strip() for line in lines) or \
            any('finished running' in line.decode('utf-8').strip() for line in lines)
        return stop_condition

    def _stop_tool(self):
        stop_filepath = self.stop_filepath()
        logger.debug('Collector stopped: {}'.format(stop_filepath))
        touch(stop_filepath)

    def stop_filepath(self):
        return os.path.join(current_dir(), 'stop_mon.log')


class EmilCollector(Collector):
    @typed(logs_directory=Filepath(), tool_directory=Filepath())
    def __init__(self, logs_directory, flags, tool_directory=TOOL_TEMP_DIRECTORY):
        super(EmilCollector, self).__init__()
        self._logs_directory = logs_directory
        self._tool_directory = os.path.join(tool_directory, 'emil_collector')
        self._capturer = None
        self._flags = flags

    def start(self):
        if dryrun_is_set():
            return

        try:
            ToolDownloader(self._tool_directory).download()
        except InvalidRepo:
            logger.warning('There was a problem while getting gnb_tool. Emil Collector disabled')
            return

        ConfigInjector(self._tool_dir(), CONFIG).set()
        self._capturer = GnbLogs(self._tool_dir(), self._flags)
        self._capturer.run()

    @with_callback_name('Stop Collecting Emil Logs')
    def stop(self):
        if self._capturer is not None:
            self._capturer.stop()
            self._move_collected_logs()
            self._cleanup()

    def _tool_dir(self):
        return os.path.join(self._tool_directory, 'gnb_logs')

    def _move_collected_logs(self):
        for filename in os.listdir(current_dir()):
            shutil.copy(self._capturer.readines_log_path(), self._logs_directory)
            if '10.0.1.2' in filename and filename.endswith('.zip'):
                shutil.move(os.path.join(current_dir(), filename), self._logs_directory)

    def _cleanup(self):
        if os.path.exists(self._capturer.stop_filepath()):
            os.remove(self._capturer.stop_filepath())
